import pathlib,json,base64,gzip,hashlib,importlib.util,sys,threading,traceback
from datetime import datetime as cg_control_datetime,timezone as cg_control_timezone
assert not globals().get('recovery_controls_thread') or not recovery_controls_thread.is_alive(),'Control publication already active.'
qrec_control_root=pathlib.Path('/content/mathvisionkid_recovery_20261026')
qrec_control_payload={'four_controls_transaction.py': '', 'prepare_control_stage.py': '', 'prepare_four_controls_runtime.py': '', 'recovery26_phase/launch_receipt.json': '', 'recovery26_phase/native_backend_20261026.py': '', 'recovery26_phase/owner_run_scope.json': '', 'recovery26_phase/phase_run_metadata.json': '', 'recovery26_phase/preparation_provenance.json': '', 'recovery26_phase/recovery_policy_20261026.py': '', 'recovery26_phase/recovery_worker_20261026.py': '', 'recovery26_phase/root_reviewed_training_plan.json': '', 'recovery26_phase/stage_receipt.json': '', 'recovery26_phase/staged_code_pins.json': ''}
qrec_control_hashes={'four_controls_transaction.py': 'e50d53815215af6902ebe772b3960f0c3023afd010b535d1a3c26eb1d127b37b', 'prepare_control_stage.py': '7498845636d7829c389f87b54d6fa8e0747c49677128e3473dd79c22e1b4f07e', 'prepare_four_controls_runtime.py': '90f11adb012fd4c42b92c8193452201837d52173496b3520404c42e550b82530', 'recovery26_phase/launch_receipt.json': '33a5771fe005303c14d625083ea358b9e1a7c8ba020806f57eca6445a9028ca6', 'recovery26_phase/native_backend_20261026.py': '66aa1473bb6835497fb59b16ab0c76e2a609eec0358d9b7cd03f2662e3f3a046', 'recovery26_phase/owner_run_scope.json': '8af8bebf841452def1ee908d6040feaa605abb06e4e17e7c6e06f7afe9cac758', 'recovery26_phase/phase_run_metadata.json': 'bbd16eb9123dd842fa8e915e56a8fea795eda15560478b39d21a93ccf22a1c1d', 'recovery26_phase/preparation_provenance.json': '7e5794dc5e8b7b2f62f4d28423494fb95ea7eb392d1fd0fc7e8a25a0a0c853dc', 'recovery26_phase/recovery_policy_20261026.py': '648a6a8f48ded0bf7cb2615451b895e9b3a7d72bfdd294430ec58ce4029384fd', 'recovery26_phase/recovery_worker_20261026.py': 'b618f2d961dd0d342f006a8b07abe39268962fc0bdcab43622c425ee2bf67d4f', 'recovery26_phase/root_reviewed_training_plan.json': '1234d9d4159c4326ea2d423da124005aff7f08cfe1650e91b1b36e30c3f0c4fa', 'recovery26_phase/stage_receipt.json': '95aedc9761ee6aad372b8f8422bdc4b0cd3aaa93f868cf4eb66147c0df32ff54', 'recovery26_phase/staged_code_pins.json': 'c4433ebf9721858d86c06a97b78a7382b8328bb6502f15d272197767c3648509'}
qrec_control_credentials_name='recovery_credentials'
qrec_control_process_name='conditional_training_process'
qrec_control_run_metadata={'schema': 'MathVisionKid.recovery_20261026.phase_metadata.v1', 'phase': 'MODEL_LOADING_OPTIMIZER_APPROVAL_HELD', 'run_folder_id': '10drqDBNTGy60JBIUqanc9fFHFopCUivq', 'source_rows': 16000, 'source_cases': 4000, 'derived_rows': 6625, 'hard_deadline_utc': '2026-10-26T11:14:18Z', 'train_cutoff_utc': '2026-10-26T11:04:18Z', 'reserve_seconds': 600, 'optimizer_update_observed': False, 'model_improvement_established': False, 'prior_adapter_rejected': True, 'previous_review_drive_id': '1gz9LMFrDvWnbHp5ycOuyQm223i5SGptL', 'source_and_corpus_preserved': True, 'human_review_claimed': False, 'production_approved': False, 'paid_resources': False, 'skills_applied': ['plugin-management', 'google-drive:google-drive']}
qrec_control_context=gzip.decompress(base64.b64decode(''))
assert hashlib.sha256(qrec_control_context).hexdigest()=='20dc2d551ed9a68f60cac78fd837c0248d3cf44e332b7b9a8f749bae11b1ac67'
assert qrec_control_root.is_dir(),'Runtime root must already exist; this script does not launch training.'
assert qrec_control_credentials_name in globals(),'Explicit authenticated credentials global is missing.'
assert qrec_control_process_name in globals(),'Actual worker process global is missing; do not invent an observation.'
for qrec_name,qrec_encoded in qrec_control_payload.items():
 qrec_data=base64.b64decode(qrec_encoded);assert hashlib.sha256(qrec_data).hexdigest()==qrec_control_hashes[qrec_name]
 qrec_path=qrec_control_root/qrec_name;qrec_path.parent.mkdir(parents=True,exist_ok=True)
 if qrec_path.exists():assert qrec_path.read_bytes()==qrec_data,'Existing evidence differs: '+qrec_name
 else:qrec_path.write_bytes(qrec_data)
qrec_context_path=qrec_control_root/('canonical_context_'+'20dc2d551ed9a68f60cac78fd837c0248d3cf44e332b7b9a8f749bae11b1ac67'+'.md')
if qrec_context_path.exists():assert qrec_context_path.read_bytes()==qrec_control_context
else:qrec_context_path.write_bytes(qrec_control_context)
def qrec_load_control(name):
 spec=importlib.util.spec_from_file_location('quality_recovery_'+name,qrec_control_root/(name+'.py'))
 mod=importlib.util.module_from_spec(spec);sys.modules[spec.name]=mod;spec.loader.exec_module(mod);return mod
qrec_prepare_controls=qrec_load_control('prepare_four_controls_runtime')
qrec_control_transaction=qrec_load_control('four_controls_transaction')
def _publish_quality_recovery_controls():
 status_path=qrec_control_root/'four_controls_publication_status.json'
 def status(value):
  tmp=status_path.with_suffix('.pending');tmp.write_bytes(qrec_prepare_controls.json_bytes(value));tmp.replace(status_path)
 work=qrec_control_root/'four_controls_publication'/cg_control_datetime.now(cg_control_timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
 try:
  status({'state':'READING_PARENTS','work':str(work),'branch':'recovery_20261026'})
  credentials=globals()[qrec_control_credentials_name]
  parents=qrec_control_transaction.download_current_parents_with_credentials(credentials,qrec_prepare_controls.IDS,work/'parents',min_request_interval=1.25)
  process=globals()[qrec_control_process_name]
  exit_code=process.poll()
  observed={'observed_utc':cg_control_datetime.now(cg_control_timezone.utc).isoformat(),'worker_alive':exit_code is None,'worker_exit':exit_code,'pid':process.pid}
  actual=qrec_prepare_controls.capture_branch_metadata(qrec_control_root,worker_observation=observed)
  evidence={name:qrec_control_root/name for name in qrec_control_payload}
  prepared=qrec_prepare_controls.prepare_controls(parents,qrec_control_context,actual,evidence,work/'prepared',run_metadata=qrec_control_run_metadata)
  assert prepared['run_metadata_sha256']=='396720504ea6c54fdec75238a0c29416c99b93f2e46a72e1a3f5365491719a68'
  status({'state':'PREPARED','work':str(work),'observation':actual,'controls':prepared['controls']})
  receipt=qrec_control_transaction.publish_with_credentials(credentials,prepared['parents'],prepared['controls'],work,receipt_path=work/'four_controls_raw_verified.json',min_request_interval=1.25)
  assert [item['kind'] for item in receipt['verified_writes']]==['progress','chat','context','state']
  assert all(item['fresh_raw_readback_verified'] for item in receipt['verified_writes'])
  (qrec_control_root/'four_controls_verified_manifest.json').write_bytes(qrec_prepare_controls.json_bytes(receipt))
  status({'state':'COMPLETE_RAW_VERIFIED','work':str(work),'receipt':receipt,'canonical_context_sha256':'20dc2d551ed9a68f60cac78fd837c0248d3cf44e332b7b9a8f749bae11b1ac67','run_metadata_sha256':'396720504ea6c54fdec75238a0c29416c99b93f2e46a72e1a3f5365491719a68'})
 except Exception as error:
  status({'state':'ERROR','work':str(work),'error':repr(error),'traceback':traceback.format_exc()})
recovery_controls_thread=threading.Thread(target=_publish_quality_recovery_controls,name='MathVisionKidConditionalGroundingFourControls',daemon=True)
recovery_controls_thread.start()
print(json.dumps({'controls_thread_started':True,'canonical_context_sha256':'20dc2d551ed9a68f60cac78fd837c0248d3cf44e332b7b9a8f749bae11b1ac67','run_metadata_sha256':'396720504ea6c54fdec75238a0c29416c99b93f2e46a72e1a3f5365491719a68','data_or_weights_changed':False}))
